package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func isInt(t string) bool {
	s := t
	if strings.HasPrefix(s, "-") {
		s = s[1:]
	}
	if s == "" {
		return false
	}
	for _, c := range s {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

func eval(line string) string {
	var st []int64
	for _, t := range strings.Fields(line) {
		switch t {
		case "+", "-", "*", "/":
			if len(st) < 2 {
				return "error: underflow"
			}
			a, b := st[len(st)-2], st[len(st)-1]
			st = st[:len(st)-2]
			var r int64
			switch t {
			case "+":
				r = a + b
			case "-":
				r = a - b
			case "*":
				r = a * b
			case "/":
				if b == 0 {
					return "error: divzero"
				}
				r = a / b
			}
			st = append(st, r)
		default:
			if !isInt(t) {
				return "error: token"
			}
			v, err := strconv.ParseInt(t, 10, 64)
			if err != nil {
				return "error: token"
			}
			st = append(st, v)
		}
	}
	if len(st) != 1 {
		return "error: leftover"
	}
	return strconv.FormatInt(st[0], 10)
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<28)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for sc.Scan() {
		line := sc.Text()
		if strings.TrimSpace(line) == "" {
			continue
		}
		fmt.Fprintln(w, eval(line))
	}
}
